/* ── Page break (:::pagebreak) ────────────────────────────────────────────── */
/* Nothing on screen: the paged sheet (report_fastr_paged.ts) ends the page
   there, and the editor draws its own labelled divider. */
.fm-pagebreak { display: block; height: 0; margin: 0; padding: 0; overflow: hidden; }

/* ── Document header (:::report) — applied to <html> ──────────────────────── */
.fm-doc--wide { --fm-measure: 74rem; }
.fm-doc--full { --fm-measure: 100rem; }


.fm-tone.fm-tone--paper {
  background: var(--fm-paper-ground);
  --fm-ink: var(--fm-paper-ground-ink);
  --fm-accent: var(--fm-accent-ground);
  --fm-accent-text: #4e6f94;
  --fm-callout-color: var(--fm-accent-ground);
  --fm-ink-muted: color-mix(in srgb, var(--fm-paper-ground-ink) 72%, transparent);
  --fm-border: color-mix(in srgb, var(--fm-paper-ground-ink) 26%, transparent);
  --fm-surface: color-mix(in srgb, var(--fm-paper-ground-ink) 10%, transparent);
  --fm-surface-alt: color-mix(in srgb, var(--fm-paper-ground-ink) 16%, transparent);
  --fm-info: var(--fm-info-light);
  --fm-success: var(--fm-success-light);
  --fm-warning: var(--fm-warning-light);
  --fm-danger: var(--fm-danger-light);
  color: var(--fm-paper-ground-ink);
}
.fm-tone.fm-tone--ink {
  background: var(--fm-ink-ground);
  --fm-ink: var(--fm-ink-ground-ink);
  --fm-accent: var(--fm-ink-ground-ink);
  --fm-accent-text: var(--fm-ink-ground-ink);
  --fm-callout-color: var(--fm-ink-ground-ink);
  --fm-ink-muted: color-mix(in srgb, var(--fm-ink-ground-ink) 72%, transparent);
  --fm-border: color-mix(in srgb, var(--fm-ink-ground-ink) 26%, transparent);
  --fm-surface: color-mix(in srgb, var(--fm-ink-ground-ink) 10%, transparent);
  --fm-surface-alt: color-mix(in srgb, var(--fm-ink-ground-ink) 16%, transparent);
  --fm-info: var(--fm-info-dark);
  --fm-success: var(--fm-success-dark);
  --fm-warning: var(--fm-warning-dark);
  --fm-danger: var(--fm-danger-dark);
  color: var(--fm-ink-ground-ink);
}
.fm-tone.fm-tone--accent {
  background: var(--fm-accent-ground);
  --fm-ink: var(--fm-accent-ground-ink);
  --fm-accent: var(--fm-accent-ground-ink);
  --fm-accent-text: var(--fm-accent-ground-ink);
  --fm-callout-color: var(--fm-accent-ground-ink);
  --fm-ink-muted: color-mix(in srgb, var(--fm-accent-ground-ink) 72%, transparent);
  --fm-border: color-mix(in srgb, var(--fm-accent-ground-ink) 26%, transparent);
  --fm-surface: color-mix(in srgb, var(--fm-accent-ground-ink) 10%, transparent);
  --fm-surface-alt: color-mix(in srgb, var(--fm-accent-ground-ink) 16%, transparent);
  --fm-info: var(--fm-info-dark);
  --fm-success: var(--fm-success-dark);
  --fm-warning: var(--fm-warning-dark);
  --fm-danger: var(--fm-danger-dark);
  color: var(--fm-accent-ground-ink);
}
.fm-tone.fm-tone--warm {
  background: var(--fm-warm-ground);
  --fm-ink: var(--fm-warm-ground-ink);
  --fm-accent: var(--fm-warm-ground-ink);
  --fm-accent-text: var(--fm-warm-ground-ink);
