/* ── Page break (:::pagebreak) ────────────────────────────────────────────── */
/* Nothing on screen: the paged sheet (report_fastr_paged.ts) ends the page
   there, and the editor draws its own labelled divider. */
:root .fm-live-scope .fm-pagebreak { display: block; height: 0; margin: 0; padding: 0; overflow: hidden; }

/* ── Document header (:::report) — applied to <html> ──────────────────────── */
:root .fm-live-scope .fm-doc--wide { --fm-measure: 74rem; }
:root .fm-live-scope .fm-doc--full { --fm-measure: 100rem; }

/* Scoped context (a picker tile): the viewport is not the page, so nothing may
   bleed to it — the geometry is neutralised at the root and every band, cover
   and full-width figure follows. */
:root .fm-live-scope { --fm-bleed-margin: 0; --fm-bleed-pad: 1.4em; }
:root .fm-live-scope .fm-cover { min-height: 0; }


:root .fm-live-scope .fm-tone.fm-tone--paper {
  background: var(--fm-paper-ground);
  --fm-ink: var(--fm-paper-ground-ink);
  --fm-accent: var(--fm-accent-ground);
  --fm-accent-text: #4e6f94;
  --fm-callout-color: var(--fm-accent-ground);
  --fm-ink-muted: color-mix(in srgb, var(--fm-paper-ground-ink) 72%, transparent);
  --fm-border: color-mix(in srgb, var(--fm-paper-ground-ink) 26%, transparent);
  --fm-surface: color-mix(in srgb, var(--fm-paper-ground-ink) 10%, transparent);
  --fm-surface-alt: color-mix(in srgb, var(--fm-paper-ground-ink) 16%, transparent);
  --fm-info: var(--fm-info-light);
  --fm-success: var(--fm-success-light);
  --fm-warning: var(--fm-warning-light);
  --fm-danger: var(--fm-danger-light);
  color: var(--fm-paper-ground-ink);
}
:root .fm-live-scope .fm-tone.fm-tone--ink {
  background: var(--fm-ink-ground);
  --fm-ink: var(--fm-ink-ground-ink);
  --fm-accent: var(--fm-ink-ground-ink);
  --fm-accent-text: var(--fm-ink-ground-ink);
  --fm-callout-color: var(--fm-ink-ground-ink);
  --fm-ink-muted: color-mix(in srgb, var(--fm-ink-ground-ink) 72%, transparent);
  --fm-border: color-mix(in srgb, var(--fm-ink-ground-ink) 26%, transparent);
  --fm-surface: color-mix(in srgb, var(--fm-ink-ground-ink) 10%, transparent);
  --fm-surface-alt: color-mix(in srgb, var(--fm-ink-ground-ink) 16%, transparent);
  --fm-info: var(--fm-info-dark);
  --fm-success: var(--fm-success-dark);
  --fm-warning: var(--fm-warning-dark);
  --fm-danger: var(--fm-danger-dark);
  color: var(--fm-ink-ground-ink);
}
:root .fm-live-scope .fm-tone.fm-tone--accent {
  background: var(--fm-accent-ground);
  --fm-ink: var(--fm-accent-ground-ink);
  --fm-accent: var(--fm-accent-ground-ink);
  --fm-accent-text: var(--fm-accent-ground-ink);
  --fm-callout-color: var(--fm-accent-ground-ink);
  --fm-ink-muted: color-mix(in srgb, var(--fm-accent-ground-ink) 72%, transparent);
  --fm-border: color-mix(in srgb, var(--fm-accent-ground-ink) 26%, transparent);
  --fm-surface: color-mix(in srgb, var(--fm-accent-ground-ink) 10%, transparent);
  --fm-surface-alt: color-mix(in srgb, var(--fm-accent-ground-ink) 16%, transparent);
  --fm-info: var(--fm-info-dark);
  --fm-success: var(--fm-success-dark);
  --fm-warning: var(--fm-warning-dark);
  --fm-danger: var(--fm-danger-dark);
  color: var(--fm-accent-ground-ink);
}
:root .fm-live-scope .fm-tone.fm-tone--warm {
  background: var(--fm-warm-ground);
  --fm-ink: var(--fm-warm-ground-ink);
  --fm-accent: var(--fm-warm-ground-ink);
  --fm-accent-text: var(--fm-warm-ground-ink);
  --fm-callout-color: var(--fm-warm-ground-ink);
  --fm-ink-muted: color-mix(in srgb, var(--fm-warm-ground-ink) 72%, transparent);
  --fm-border: color-mix(in srgb, var(--fm-warm-ground-ink) 26%, transparent);
  --fm-surface: color-mix(in srgb, var(--fm-warm-ground-ink) 10%, transparent);
  --fm-surface-alt: color-mix(in srgb, var(--fm-warm-ground-ink) 16%, transparent);
  --fm-info: var(--fm-info-dark);
  --fm-success: var(--fm-success-dark);
  --fm-warning: var(--fm-warning-dark);
  --fm-danger: var(--fm-danger-dark);
  color: var(--fm-warm-ground-ink);
}

:root .fm-live-scope h2 { border-bottom-color: var(--fm-border); }
:root .fm-live-scope .fm-stat { border-color: var(--fm-border); }
:root .fm-live-scope .fm-quote { border-left-color: var(--fm-accent); }
:root .fm-live-scope .fm-steps > *::before { color: var(--fm-accent-text); }
:root .fm-live-scope thead th { background: var(--fm-surface-alt); }

css_custom/default:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
:root {
  --fm-page: #101820;
  --fm-paper: #101820;
  --fm-warm: #936653;
  --fm-light-ink: #f4f1ea;
  --fm-dark-ink: #101820;
  --fm-surface: #192128;
  --fm-surface-alt: #222930;
  --fm-ink: #f4f1ea;
  --fm-ink-muted: #9d9f9d;
  --fm-accent: #e0a526;
  --fm-border: #393f44;
  --fm-radius: 6px;
  --fm-border-width: 1px;
  /* What a border at the theme's width takes beyond the default theme's
     1px: every structure rule drawn at --fm-border-width gives it back out
     of the padding beside it, so a heavier theme's boxes stand as tall and
     hold as wide a column as the default theme's (FASTR_THEME_SPECS). */
  --fm-border-give: calc(1px - 1px);
  --fm-body-tracking: 0em;
  --fm-body-size: 16px;
  --fm-body-leading: 1.55;
  --fm-bullet: "\2022 ";
  --fm-fit-caption: 1;
  --fm-fit-callout-title: 1;
  --fm-fit-card-title: 1;
  --fm-fit-stat-value: 1;
  --fm-fit-stat-label: 1;
  --fm-fit-kicker: 1;
  --fm-fit-th: 1;
  --fm-fit-quote: 1;
  --fm-fit-cite: 1;
  --fm-font-body: Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --fm-font-heading: Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --fm-heading-weight: 700;
  --fm-heading-tracking: -0.01em;
  --fm-heading-case: none;
  --fm-measure: 56rem;
  --fm-callout-color: #e0a526;
  --fm-h1-size: 2.15em;
  --fm-h1-weight: var(--fm-heading-weight);
  --fm-h1-line-height: 1.2;
  --fm-h1-fit: 1;
  --fm-h2-size: 1.55em;
  --fm-h2-weight: var(--fm-heading-weight);
  --fm-h2-line-height: 1.2;
  --fm-h2-fit: 1;
  --fm-h3-size: 1.2em;
  --fm-h3-weight: var(--fm-heading-weight);
  --fm-h3-line-height: 1.2;
  --fm-h3-fit: 1;
  --fm-h4-size: 1em;
  --fm-h4-weight: var(--fm-heading-weight);
  --fm-h4-line-height: 1.2;
  --fm-h4-fit: 1;
  --fm-h5-size: 1em;
  --fm-h5-weight: var(--fm-heading-weight);
  --fm-h5-line-height: 1.2;
  --fm-h5-fit: 1;
  --fm-h6-size: 1em;
  --fm-h6-weight: var(--fm-heading-weight);
  --fm-h6-line-height: 1.2;
  --fm-h6-fit: 1;
  --fm-paper-ground: #222930;
  --fm-paper-ground-ink: #f4f1ea;
  --fm-ink-ground: #f4f1ea;
  --fm-ink-ground-ink: #101820;
  --fm-accent-ground: #e0a526;
  --fm-accent-ground-ink: #f4f1ea;
  --fm-warm-ground: #936653;
  --fm-warm-ground-ink: #f4f1ea;
  --fm-accent-text: #e0a526;
  --fm-mark-accent-weight: inherit;
  --fm-info-light: #826623;
  --fm-info-dark: #e0a526;
  --fm-success-light: #826623;
  --fm-success-dark: #e0a526;
  --fm-warning-light: #494635;
  --fm-warning-dark: #786c46;
  --fm-danger-light: #58433c;
  --fm-danger-dark: #936653;
  --fm-info: var(--fm-info-dark);
  --fm-success: var(--fm-success-dark);
  --fm-warning: var(--fm-warning-dark);
  --fm-danger: var(--fm-danger-dark);
}

html, body {
  background: var(--fm-page);
  color: var(--fm-ink);
  font-family: var(--fm-font-body);
  letter-spacing: var(--fm-body-tracking, 0em);
  /* Full-bleed geometry, defined ONCE: a band cancels the centred column with
     a viewport-width negative margin, then insets its own content back to the
     measure. Print and the scoped picker tiles have no viewport to bleed into,
     so they neutralise the pair here rather than resetting each selector. */
  --fm-bleed-margin: calc(50% - 50vw);
  --fm-bleed-pad: max(1.5rem, calc((100vw - var(--fm-measure)) / 2 + 1.5rem));
}
/* The PAGE ground lives on <html>, not <body>: a full-bleed band is a body
   child that escapes the column with a viewport-width negative margin, and
   document-level settings (:::report) are applied to <html> so they cover the
   whole page rather than just the text column. overflow-x on the root absorbs
   the scrollbar width that 100vw would otherwise overflow by. */
body { max-width: var(--fm-measure); background: transparent; }
/* The theme's body type (fastrBodyType). On <body>, never <html>: a rem
   is the root's, and the column and cover lengths are written in rem. A
   scoped sheet sets nothing here: the editor's lines read the same two
   vars on .cm-content (livePreviewTheme), and a picker tile sets its own. */
body { font-size: var(--fm-body-size); line-height: var(--fm-body-leading); }
h1, h2, h3, h4, h5, h6 {
  font-family: var(--fm-font-heading);
  letter-spacing: var(--fm-heading-tracking);
  text-transform: var(--fm-heading-case);
  color: var(--fm-ink);
  margin: calc(1.8em * var(--fm-h-fit, 1)) 0 calc(0.4em * var(--fm-h-fit, 1));
}
/* An h1 is a SECTION (the cover carries the title): its own larger em
   gives it a little more room above than an h2 (FASTR_HEADING_SPACE). The
   document's first block has none (below, and the paged sheet's title
   rule); a cover's title sits where its layout puts it. --fm-h-fit is the
   level's width fit (FastrThemeSpec.headingFit): the size var is already
   divided by it, so every em a heading rule writes for its box (a margin, a
   rule's padding, a template's own size) multiplies by it to keep the
   default theme's box. */
h1 { --fm-h-fit: var(--fm-h1-fit, 1); font-size: var(--fm-h1-size); font-weight: var(--fm-h1-weight); line-height: var(--fm-h1-line-height); }
h2 { --fm-h-fit: var(--fm-h2-fit, 1); font-size: var(--fm-h2-size); font-weight: var(--fm-h2-weight); line-height: var(--fm-h2-line-height); }
h3 { --fm-h-fit: var(--fm-h3-fit, 1); font-size: var(--fm-h3-size); font-weight: var(--fm-h3-weight); line-height: var(--fm-h3-line-height); }
h4 { --fm-h-fit: var(--fm-h4-fit, 1); font-size: var(--fm-h4-size); font-weight: var(--fm-h4-weight); line-height: var(--fm-h4-line-height); }
h5 { --fm-h-fit: var(--fm-h5-fit, 1); font-size: var(--fm-h5-size); font-weight: var(--fm-h5-weight); line-height: var(--fm-h5-line-height); }
h6 { --fm-h-fit: var(--fm-h6-fit, 1); font-size: var(--fm-h6-size); font-weight: var(--fm-h6-weight); line-height: var(--fm-h6-line-height); }
h1 { margin-top: calc(1.5em * var(--fm-h-fit, 1)); }
/* The default theme's h2 rule, as every theme's box: a theme recolours it,
   restyles it, or draws a heavier one by giving the extra width back out of
   the padding (the geometry rule at FASTR_THEME_SPECS). */
h2 {
  padding-bottom: calc(0.25em * var(--fm-h-fit, 1));
  border-bottom: 1px solid transparent;
}
body > :first-child { margin-top: 0; }
p { margin: 0 0 1em; }
/* A paragraph's or heading's own alignment ({align=…},
   fastr_paragraph_align.ts); a class beats a theme's own heading rule. */
.fm-align-left { text-align: left; }
.fm-align-center { text-align: center; }
.fm-align-right { text-align: right; }
.fm-align-justify { text-align: justify; }
/* A blank source line beyond the paragraph separator (report_fastr_markdown's
   fm_spaces): one line of the body's height, empty, exactly the height the
   editor gives that line, so Enter moves the page the same way on both. */
.fm-space { height: 1lh; margin: 0; }
a { color: var(--fm-accent); }
strong { font-weight: 700; }
ul, ol { margin: 0 0 1em; --fm-mt: 0px; --fm-mb: 1em; padding-left: 1.4em; list-style: none; }
li { margin: 0.25em 0; position: relative; }
/* The markers as glyphs at the left of the list's own indent, as the editor
   draws them on its lines (cm-fm-bullet), so an item's text starts where the
   editor's does. The contents block is an ol of its own. */
ul > li::before { content: var(--fm-bullet, "\2022"); position: absolute; left: -1.4em; width: 1.4em; }
ol:not(.fm-toc__list) { counter-reset: fm-ol; }
ol:not(.fm-toc__list) > li { counter-increment: fm-ol; }
ol:not(.fm-toc__list) > li::before { content: counter(fm-ol) "."; position: absolute; left: -1.4em; width: 1.4em; }
hr { border: 0; border-top: 1px solid var(--fm-border); margin: 2em 0; }
code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.9em;
  background: var(--fm-surface-alt);
  padding: 0.1em 0.3em;
  border-radius: min(var(--fm-radius), 3px);
}
/* The browser's own 1em margins, declared: the editor measures print's
   margins under the app's base sheet, which zeroes a pre's. */
pre {
  margin: 1em 0;
  background: var(--fm-surface-alt);
  border-radius: var(--fm-radius);
  padding: 0.9em 1.1em;
  overflow-x: auto;
}
pre code { background: none; padding: 0; }
table { width: 100%; margin: 0 0 1.4em; --fm-mt: 0px; --fm-mb: 1.4em; font-size: 0.94em; }
th, td {
  border-bottom: 1px solid var(--fm-border);
  padding: 0.5em 0.7em;
  text-align: left;
  vertical-align: top;
}
/* tr.fm-page-gutter-repeat is the editor's copy of a table's header rows on
   a page the table continues on, which print's runner clones into a real
   thead (live_preview_extension): it takes the header treatment too, or the
   continuation stands a pixel short of print's. */
thead th, tr.fm-page-gutter-repeat > th {
  border-bottom: 2px solid var(--fm-ink);
  font-weight: 700;
  font-size: calc(1em / var(--fm-fit-th, 1));
  line-height: calc(var(--fm-body-leading, 1.55) * var(--fm-fit-th, 1));
  padding: calc(0.5em * var(--fm-fit-th, 1)) calc(0.7em * var(--fm-fit-th, 1));
}
blockquote {
  margin: 1.4em 0;
  --fm-mt: 1.4em;
  --fm-mb: 1.4em;
  padding: 0.2em 0 0.2em 1.1em;
  border-left: 3px solid var(--fm-border);
  color: var(--fm-ink-muted);
}
/* The quote's own padding sets it off; its paragraphs bring no margin of
   their own to the box (the editor draws the quote as lines and has none). */
blockquote > :first-child { margin-top: 0; }
blockquote > :last-child { margin-bottom: 0; }
/* A word longer than the column (a URL) breaks rather than run past the
   page; the editor's lines wrap the same way. */
p, li, td, th, h1, h2, h3, h4, h5, h6 { overflow-wrap: break-word; }

/* ── Figures (an embed on its own line becomes a captioned figure) ────────── */
.fm-figure { margin: 1.6em 0; --fm-mt: 1.6em; --fm-mb: 1.6em; }
/* A figure is the width its author gave it, the same wherever it falls
   (fastr_markdown_blocks.ts, "Figure widths"): the text column by default,
   a share of it at width=small|medium (--fm-fig-share). Its height is its
   own aspect at that width. The ONLY height limit is the page ceiling
   (FIGURE_CAP: --fm-page-area, which the paged sheet and the editor's page
   boxes set, less the measured figure reserve, so a section heading and the
   figure always share a page; a browser window falls back to its own
   height), which only a figure shaped taller than the page ever meets; it
   then narrows, centred, to the tallest that fits. An image is never
   stretched past its own pixels (width: auto). */
.fm-figure--small { --fm-fig-share: 0.5; }
.fm-figure--medium { --fm-fig-share: 0.75; }
.fm-figure img {
  display: block;
  width: auto;
  max-width: calc(100% * var(--fm-fig-share, 1));
  max-height: calc(var(--fm-page-area, 100vh) - var(--fm-fig-reserve, calc(var(--fm-page-area, 100vh) * 0.15)));
  margin-inline: auto;
}
/* The editor's stand-in while a figure renders (report_html.ts): the same
   width and ceiling, so the page flow does not move when the raster
   replaces it. */
.fm-figure .report-embed-pending {
  width: calc(100% * var(--fm-fig-share, 1));
  max-height: calc(var(--fm-page-area, 100vh) - var(--fm-fig-reserve, calc(var(--fm-page-area, 100vh) * 0.15)));
  margin-inline: auto;
}
/* The editor's LIVE chart mount (live_preview_extension applyFigureSize):
   the raster's aspect (--fm-fig-w/h) at the figure's share of the column,
   under the same ceiling, narrowed and centred exactly as the img above,
   sized before the chart draws; the canvas inside is cut to the box (it lays
   out to the same aspect, give or take a pixel of rounding). */
.fm-figure [data-embed-kind="figure"][data-fm-sized] {
  --fm-fig-cap: calc(var(--fm-page-area, 100vh) - var(--fm-fig-reserve, calc(var(--fm-page-area, 100vh) * 0.15)));
  aspect-ratio: var(--fm-fig-w) / var(--fm-fig-h);
  width: min(calc(100% * var(--fm-fig-share, 1)), calc(var(--fm-fig-cap) * var(--fm-fig-w) / var(--fm-fig-h)));
  margin-inline: auto;
  overflow: hidden;
}
/* A mount still waiting for its size draws its chart at the chart's own
   height meanwhile: under the ceiling like a printed figure, so a figure can
   never stand a page tall while it waits (the editor sizes the mount from
   the drawn canvas itself a frame later). */
.fm-figure [data-embed-kind="figure"][data-fm-pending] {
  max-height: calc(var(--fm-page-area, 100vh) - var(--fm-fig-reserve, calc(var(--fm-page-area, 100vh) * 0.15)));
  overflow: hidden;
}
/* A restyled text role (a caption, a callout's title, a stat's value…) is
   set at its size divided by the theme's width fit for it (--fm-fit-<role>,
   FastrThemeSpec.textFit) on leading multiplied by it, and every em its box
   writes multiplies by it: the role wraps where the default theme's does and
   stands as tall, whatever face, case or tracking the theme gives it. */
.fm-figure__caption {
  margin-top: calc(0.5em * var(--fm-fit-caption, 1));
  font-size: calc(0.85em / var(--fm-fit-caption, 1));
  color: var(--fm-ink-muted);
  line-height: calc(1.4 * var(--fm-fit-caption, 1));
}

/* ── Callouts ─────────────────────────────────────────────────────────────── */
.fm-callout {
  margin: 1.5em 0;
  --fm-mt: 1.5em;
  --fm-mb: 1.5em;
  padding: 1em 1.2em;
  background: var(--fm-surface);
  border-left: 4px solid var(--fm-callout-color);
  border-radius: var(--fm-radius);
}
.fm-callout > :last-child { margin-bottom: 0; }
.fm-callout__title {
  font-family: var(--fm-font-heading);
  font-weight: 700;
  font-size: calc(1em / var(--fm-fit-callout-title, 1));
  line-height: calc(var(--fm-body-leading, 1.55) * var(--fm-fit-callout-title, 1));
  color: var(--fm-callout-color);
  margin-bottom: calc(0.35em * var(--fm-fit-callout-title, 1));
}
.fm-callout--note { --fm-callout-color: var(--fm-accent-text); }
.fm-callout--info { --fm-callout-color: var(--fm-info); }
.fm-callout--success { --fm-callout-color: var(--fm-success); }
.fm-callout--warning { --fm-callout-color: var(--fm-warning); }
.fm-callout--danger { --fm-callout-color: var(--fm-danger); }

/* ── Inline role marks — [fell 12 points]{.danger} ────────────────────────── */
/* The token is read HERE, on the span, never through a --fm-mark-* alias: a
   --fm-mark-danger: var(--fm-danger) declared on :root would substitute at
   computed-value time and inherit the SUBSTITUTED colour, so re-scoping
   --fm-danger inside a dark band would not move the mark. Reading it on the
   span means every ground rule that re-scopes the semantic tokens already
   works for marks, with no rule of its own. Doubled class for the same reason
   the tones double theirs — a theme's extraCss must not outrank a role. */
/* An accent mark must never be a no-op. In a theme whose accent cannot carry
   text on the page (Brutalist's yellow) or IS the ink (Minimal),
   --fm-accent-text degrades to ink by design — so those themes, and only
   those, mark the phrase with weight instead. */
.fm-mark.fm-mark--accent {
  color: var(--fm-accent-text);
  font-weight: var(--fm-mark-accent-weight, inherit);
}
.fm-mark.fm-mark--hl { padding: 0.05em 0.2em; border-radius: min(var(--fm-radius), 3px); }
.fm-mark.fm-mark--muted { color: var(--fm-ink-muted); }
.fm-mark.fm-mark--danger { color: var(--fm-danger); }
.fm-mark.fm-mark--warning { color: var(--fm-warning); }
.fm-mark.fm-mark--success { color: var(--fm-success); }
.fm-mark.fm-mark--info { color: var(--fm-info); }
.fm-tone--accent .fm-mark--danger,
.fm-tone--accent .fm-mark--warning,
.fm-tone--accent .fm-mark--success,
.fm-tone--accent .fm-mark--info,
.fm-tone--warm .fm-mark--danger,
.fm-tone--warm .fm-mark--warning,
.fm-tone--warm .fm-mark--success,
.fm-tone--warm .fm-mark--info { color: var(--fm-ink); }

/* ── Tiles & cards ────────────────────────────────────────────────────────── */
.fm-tiles {
  display: grid;
  gap: 1em;
  margin: 1.6em 0;
  --fm-mt: 1.6em;
  --fm-mb: 1.6em;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.fm-tiles--1 { grid-template-columns: minmax(0, 1fr); }
.fm-tiles--2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.fm-tiles--3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.fm-tiles--4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
/* A grid has no padding, so a tone on the ROW would show only through the gaps.
   Give it room and the ground reads as a panel holding the tiles. */
.fm-tiles.fm-tone, .fm-tiles.fm-has-bg,
.fm-columns.fm-tone, .fm-columns.fm-has-bg {
  padding: 1.2em;
  border-radius: var(--fm-radius);
}
.fm-card {
  /* A card on its own in the flow keeps its distance like a callout; in a
     tiles grid the gap is the grid's. The editor shows a card as a widget
     with a blank line and 0.2em of box gap on each side, which is this. */
  margin: 1.2em 0;
  --fm-mt: 1.2em;
  --fm-mb: 1.2em;
  background: var(--fm-surface);
  border: var(--fm-border-width) solid var(--fm-border);
  border-radius: var(--fm-radius);
  padding: calc(1em - var(--fm-border-give, 0px)) calc(1.1em - var(--fm-border-give, 0px));
}
.fm-tiles > .fm-card { margin: 0; }
.fm-card > :last-child { margin-bottom: 0; }
.fm-card__title {
  font-family: var(--fm-font-heading);
  font-weight: 700;
  font-size: calc(0.95em / var(--fm-fit-card-title, 1));
  line-height: calc(var(--fm-body-leading, 1.55) * var(--fm-fit-card-title, 1));
  margin-bottom: calc(0.4em * var(--fm-fit-card-title, 1));
}

/* ── Stats ────────────────────────────────────────────────────────────────── */
.fm-stat {
  background: var(--fm-surface-alt);
  border: 1px solid transparent;
  border-radius: var(--fm-radius);
  padding: 1em 1.1em;
  margin: 1.2em 0;
  --fm-mt: 1.2em;
  --fm-mb: 1.2em;
}
.fm-tiles .fm-stat, .fm-columns .fm-stat { margin: 0; }
.fm-stat > :last-child { margin-bottom: 0; }
.fm-stat__value {
  font-family: var(--fm-font-heading);
  font-size: calc(2.1em / var(--fm-fit-stat-value, 1));
  font-weight: var(--fm-heading-weight);
  letter-spacing: var(--fm-heading-tracking);
  line-height: calc(1.05 * var(--fm-fit-stat-value, 1));
  color: var(--fm-accent-text);
}
.fm-stat__label {
  font-size: calc(0.85em / var(--fm-fit-stat-label, 1));
  line-height: calc(var(--fm-body-leading, 1.55) * var(--fm-fit-stat-label, 1));
  color: var(--fm-ink-muted);
  margin-top: calc(0.25em * var(--fm-fit-stat-label, 1));
}
/* Top-aligned: on the baseline, the line box around the pill took the body
   face's ascent and descent, and a stat stood a fraction of a pixel taller
   on one theme than another. */
.fm-stat__delta {
  display: inline-block;
  vertical-align: top;
  margin-top: 0.5em;
  font-size: 0.8em;
  font-weight: 700;
  padding: 0.1em 0.45em;
  border-radius: calc(var(--fm-radius) * 999);
}
.fm-stat__delta--up {
  color: var(--fm-success);
  background: color-mix(in srgb, var(--fm-success) 16%, transparent);
}
.fm-stat__delta--down {
  color: var(--fm-danger);
  background: color-mix(in srgb, var(--fm-danger) 16%, transparent);
}
.fm-stat__delta--flat {
  color: var(--fm-ink-muted);
  background: color-mix(in srgb, var(--fm-ink) 8%, transparent);
}

/* ── Columns ──────────────────────────────────────────────────────────────── */
.fm-columns {
  display: grid;
  gap: 1.5em;
  margin: 1.6em 0;
  --fm-mt: 1.6em;
  --fm-mb: 1.6em;
  align-items: start;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.fm-columns--1 { grid-template-columns: minmax(0, 1fr); }
.fm-columns--2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.fm-columns--3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.fm-columns--4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.fm-col > :last-child { margin-bottom: 0; }
/* A column's first block (its heading, mostly) never carries its own top
   margin: the row has one, and a heading's would drop the column's text
   below its neighbour's the moment one column is coloured and the other not. */
.fm-col > :first-child, .fm-col > .cm-fm-col-ghost + * { margin-top: 0; }
/* A row with ANY coloured column is a set of panels: every column takes the
   panel inset, coloured or not, so the text of the two sides stays aligned
   and colouring one column never reflows the others'
   (fm-columns--panels, set by the renderer). */
.fm-columns--panels > .fm-col {
  padding: 1em 1.2em;
  border-radius: var(--fm-radius);
  align-self: stretch;
}
/* A toned or painted column is a panel: text flush with a coloured edge reads
   as a mistake, so it takes the same inset a toned grid does, and its first
   block sits at the top of the panel rather than under its own margin.
   Panels in one row are also read as a SET (the two sides of a comparison,
   which is what the brief asks a toned columns pair to be), so each takes
   the row's full height however its text wraps: two panels an inch apart
   read as a mistake where two columns of plain text simply end where they
   end, which is why the row itself still aligns to the start. */
.fm-col.fm-tone, .fm-col.fm-has-bg {
  padding: 1em 1.2em;
  border-radius: var(--fm-radius);
  align-self: stretch;
}
.fm-col.fm-tone > :first-child, .fm-col.fm-has-bg > :first-child { margin-top: 0; }
.fm-col--span2 { grid-column: span 2; }
.fm-col--span3 { grid-column: span 3; }
.fm-col--span4 { grid-column: span 4; }

/* ── Pull quote ───────────────────────────────────────────────────────────── */
.fm-quote {
  margin: 1.8em 0;
  --fm-mt: 1.8em;
  --fm-mb: 1.8em;
  padding: 0.2em 0 0.2em 1.2em;
  border-left: 4px solid var(--fm-accent);
  font-family: var(--fm-font-heading);
  font-size: 1.1em;
  line-height: 1.45;
  color: var(--fm-ink);
}
/* The quote's fit is its words' (its box keeps its own em, which the
   editor reads its margins in). */
.fm-quote > p {
  font-size: calc(1em / var(--fm-fit-quote, 1));
  line-height: calc(1.45 * var(--fm-fit-quote, 1));
  margin-bottom: calc(1em * var(--fm-fit-quote, 1));
}
.fm-quote > p:last-of-type { margin-bottom: 0; }
.fm-quote__cite {
  display: block;
  margin-top: calc(0.6em * var(--fm-fit-cite, 1));
  font-family: var(--fm-font-body);
  font-size: calc(0.72em / var(--fm-fit-cite, 1));
  line-height: calc(1.45 * var(--fm-fit-cite, 1));
  font-style: normal;
  color: var(--fm-ink-muted);
}

/* Unknown block name — still groups its content rather than swallowing it. */
.fm-block { margin: 1.2em 0; }

/* ── Tones: grounds by ROLE ───────────────────────────────────────────────── */
/* A tone re-scopes the ink TOKENS rather than setting color directly, so every
   descendant that reads --fm-ink (headings, muted labels, borders, rules)
   follows the ground automatically. That is also why a dark band re-inks its
   charts: the raster ground probe reads the computed background behind the
   figure, which these rules paint. */
/* The colour must be re-declared here, not just the token: an element inherits
   its parent's COMPUTED colour, which was resolved against the root ink before
   this block re-scoped --fm-ink. Headings re-resolve it (they set colour
   explicitly); paragraphs would otherwise stay dark on a dark band. */
/* Doubled for specificity, like the variants below: this rule re-declares the
   COLOUR (a child inherits its parent's computed colour, so re-scoping the ink
   token alone is not enough) and must outrank a theme's own element rules. */
.fm-tone.fm-tone { background: var(--fm-paper-ground); color: var(--fm-ink); }
/* The tone rules themselves are per theme: buildFastrToneCss. */
/* A theme may paint a heading WITH the accent (a highlighter mark). On a ground
   that is already a hue, that renders the heading invisible or garish, so the
   two hue grounds clear it. Discovered as a blank yellow cover. */
.fm-tone--accent h1, .fm-tone--accent h2, .fm-tone--accent h3,
.fm-tone--warm h1, .fm-tone--warm h2, .fm-tone--warm h3 {
  background: none;
  padding-inline: 0;
}

/* ── Literal ink (a bg colour's luminance decides it when not given) ──────── */
.fm-ink--light {
  --fm-ink: var(--fm-light-ink);
  --fm-accent: var(--fm-light-ink);
  --fm-accent-text: var(--fm-light-ink);
  --fm-callout-color: var(--fm-light-ink);
  --fm-ink-muted: color-mix(in srgb, var(--fm-light-ink) 72%, transparent);
  --fm-border: color-mix(in srgb, var(--fm-light-ink) 26%, transparent);
  --fm-surface: color-mix(in srgb, var(--fm-light-ink) 10%, transparent);
  --fm-surface-alt: color-mix(in srgb, var(--fm-light-ink) 16%, transparent);
  color: var(--fm-light-ink);
  --fm-info: var(--fm-info-dark);
  --fm-success: var(--fm-success-dark);
  --fm-warning: var(--fm-warning-dark);
  --fm-danger: var(--fm-danger-dark);
}
.fm-ink--dark {
  --fm-ink: var(--fm-dark-ink);
  --fm-accent: var(--fm-dark-ink);
  --fm-accent-text: var(--fm-dark-ink);
  --fm-callout-color: var(--fm-dark-ink);
  --fm-ink-muted: color-mix(in srgb, var(--fm-dark-ink) 68%, transparent);
  --fm-border: color-mix(in srgb, var(--fm-dark-ink) 22%, transparent);
  --fm-surface: color-mix(in srgb, var(--fm-dark-ink) 5%, transparent);
  --fm-surface-alt: color-mix(in srgb, var(--fm-dark-ink) 9%, transparent);
  color: var(--fm-dark-ink);
  --fm-info: var(--fm-info-light);
  --fm-success: var(--fm-success-light);
  --fm-warning: var(--fm-warning-light);
  --fm-danger: var(--fm-danger-light);
}

/* ── Full-bleed sections ──────────────────────────────────────────────────── */
/* The band spans the viewport (its own margins cancel the centred column) and
   then insets its CONTENT back to the column, so text stays aligned with the
   rest of the document while the ground runs edge to edge. */
.fm-band {
  display: block;
  margin: 2.5em var(--fm-bleed-margin);
  --fm-mt: 2.5em;
  --fm-mb: 2.5em;
  padding: 2.5em var(--fm-bleed-pad);
}
.fm-band > :first-child { margin-top: 0; }
/* A ticker strip under a masthead is one device, not two: consecutive bands
   sit flush rather than showing the page between them. */
.fm-band + .fm-band { margin-top: 0; }
.fm-band > :last-child { margin-bottom: 0; }
.fm-cover {
  min-height: min(72vh, 34rem);
  display: flex;
  flex-direction: column;
  justify-content: center;
  margin-top: -2.5rem;
  container-type: inline-size;
}
/* fill=page: a title page of its own; the report continues on the next. */
.fm-cover.fm-cover--fill { break-after: page; }
/* A cover's title is set at its layout's size (--fm-cover-title-size), or
   smaller when its longest word (--fm-title-chars, which the renderer
   stamps) would not fit the title's column at that size: a title word broken
   across two lines reads as a mistake. The column is the cover's own width
   (cqi) unless the layout narrows it (--fm-cover-title-col); 0.62em is a
   generous average glyph for a bold heading face. Both divide by the h1's
   width fit, so a theme's title sets as wide as the default theme's. A
   theme's rule over a heading (its ::after, set in the margin above it)
   would strike the kicker here, where the title has no margin: on a cover
   the heading keeps only the rule under it. */
.fm-cover :is(h1, h2, h3)::after { border-top: none; }
.fm-cover h1 {
  font-size: calc(min(
    var(--fm-cover-title-size, 3em),
    calc(var(--fm-cover-title-col, 100cqi) / (var(--fm-title-chars, 1) * 0.62))
  ) / var(--fm-h-fit, 1));
  margin-top: 0;
}
/* Masthead lines: the kicker sits above the title, the dek below a rule. */
.fm-kicker {
  font-family: var(--fm-font-heading);
  font-size: calc(0.75em / var(--fm-fit-kicker, 1));
  line-height: calc(var(--fm-body-leading, 1.55) * var(--fm-fit-kicker, 1));
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--fm-ink-muted);
  margin-bottom: calc(0.9em * var(--fm-fit-kicker, 1));
}
.fm-dek {
  margin-top: 1em;
  padding-top: calc(0.7em - var(--fm-border-give, 0px));
  border-top: var(--fm-border-width) solid currentColor;
  font-size: 0.95em;
  font-weight: 700;
}

/* ── Cover layouts (layout=) ──────────────────────────────────────────────── */
/* The layout is the cover's COMPOSITION; the tone is its ground, so every
   layout works on every tone. Each keeps the masthead lines as DIRECT children
   of the cover (the editor's kicker/dek islands depend on that) and is written
   in em, so the Insert menu's thumbnails shrink it faithfully. Two classes
   outrank a theme's own .fm-cover { text-align } whatever the sheet order. */

.fm-cover.fm-cover--poster h1, .fm-cover.fm-cover--spine h1,
.fm-cover.fm-cover--split h1, .fm-cover.fm-cover--minimal h1,
.fm-cover.fm-cover--block h1 { text-align: left; }
.fm-cover.fm-cover--centered h1, .fm-cover.fm-cover--frame h1 {
  text-align: center;
}

/* Centred: everything on the axis; the sub's rule becomes a short centred bar. */
.fm-cover.fm-cover--centered {
  align-items: center;
  text-align: center;
}
.fm-cover.fm-cover--centered h1 { --fm-cover-title-size: 3.6em; max-width: calc(14em * var(--fm-h-fit, 1)); }
.fm-cover.fm-cover--centered .fm-dek {
  border-top: none;
  padding-top: 0;
  max-width: 34em;
}
.fm-cover.fm-cover--centered .fm-dek::before {
  content: "";
  display: block;
  width: 3em;
  height: 0.2em;
  margin: 0 auto 1em;
  background: currentColor;
}

/* Poster: an accent bar at the head, the title set huge and pushed to the foot. */
.fm-cover.fm-cover--poster {
  justify-content: flex-end;
  text-align: left;
}
.fm-cover.fm-cover--poster::before {
  content: "";
  display: block;
  width: 5em;
  height: 0.6em;
  margin-bottom: auto;
  background: var(--fm-accent);
}
.fm-cover.fm-cover--poster h1 {
  --fm-cover-title-size: 4.4em;
  line-height: calc(0.98 * var(--fm-h-fit, 1));
  letter-spacing: -0.02em;
  max-width: calc(11em * var(--fm-h-fit, 1));
  margin-top: calc(0.4em * var(--fm-h-fit, 1));
}
.fm-cover.fm-cover--poster .fm-dek { max-width: 40em; }

/* Spine: a bound edge — an accent rule down the whole left side, the text
   hanging off it. The rule sits OUTSIDE the column so the text stays aligned. */
.fm-cover.fm-cover--spine {
  text-align: left;
  border-left: 0.6em solid var(--fm-accent);
  padding-left: calc(var(--fm-bleed-pad) - 0.6em);
}
.fm-cover.fm-cover--spine .fm-kicker { color: var(--fm-accent-text); }
.fm-cover.fm-cover--spine .fm-dek {
  border-top: none;
  padding-top: 0;
  border-left: 0.15em solid currentColor;
  padding-left: 1em;
  max-width: 36em;
}

/* Frame: a double hairline rule inset from the edges, the words centred in
   it — the printed report cover. The frame follows the theme's rule weight. */
.fm-cover.fm-cover--frame {
  position: relative;
  align-items: center;
  text-align: center;
  padding-block: 4.5em;
}
.fm-cover.fm-cover--frame::before {
  content: "";
  position: absolute;
  inset: 1.4em max(1.4em, calc(var(--fm-bleed-pad) - 1.6em));
  border: var(--fm-border-width) solid currentColor;
  outline: var(--fm-border-width) solid currentColor;
  outline-offset: 0.35em;
  pointer-events: none;
}
.fm-cover.fm-cover--frame h1 { max-width: calc(14em * var(--fm-h-fit, 1)); }
.fm-cover.fm-cover--frame .fm-dek {
  border-top: none;
  padding-top: 0;
  font-size: 0.8em;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  max-width: 34em;
}

/* Split: the kicker across the head, then the title left and the sub right
   on a vertical rule, both at the foot — an editorial spread. */
.fm-cover.fm-cover--split {
  display: grid;
  grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
  column-gap: 3em;
  align-items: end;
  align-content: space-between;
  text-align: left;
}
.fm-cover.fm-cover--split .fm-kicker {
  grid-column: 1 / -1;
  align-self: start;
  margin-bottom: calc(3em * var(--fm-fit-kicker, 1));
}
.fm-cover.fm-cover--split h1 {
  grid-column: 1;
  margin: 0;
  --fm-cover-title-size: 3.4em;
  --fm-cover-title-col: calc((100cqi - 3em) * 0.6);
  line-height: calc(1.02 * var(--fm-h-fit, 1));
}
.fm-cover.fm-cover--split > p { grid-column: 1; }
.fm-cover.fm-cover--split .fm-dek {
  grid-column: 2;
  margin-top: 0;
  border-top: none;
  padding-top: 0;
  border-left: var(--fm-border-width) solid currentColor;
  padding-left: calc(1.2em - var(--fm-border-give, 0px));
  font-weight: 400;
}

/* Minimal: top-set and quiet — a smaller title, the sub in muted ink, a
   hairline foot instead of a ground. */
.fm-cover.fm-cover--minimal {
  justify-content: flex-start;
  text-align: left;
  padding-top: 5em;
  padding-bottom: calc(2.5em - var(--fm-border-give, 0px));
  border-bottom: var(--fm-border-width) solid var(--fm-border);
}
.fm-cover.fm-cover--minimal h1 { --fm-cover-title-size: 2.6em; max-width: calc(18em * var(--fm-h-fit, 1)); }
.fm-cover.fm-cover--minimal .fm-kicker { color: var(--fm-accent-text); }
.fm-cover.fm-cover--minimal .fm-dek {
  border-top: none;
  padding-top: 0;
  font-weight: 400;
  color: var(--fm-ink-muted);
  max-width: 36em;
}

/* Block: the title set as a solid block of the accent. On the accent ground
   the block would vanish into it, so that tone keeps the plain title. */
.fm-cover.fm-cover--block { text-align: left; }
.fm-cover.fm-cover--block:not(.fm-tone--accent) h1 {
  align-self: flex-start;
  background: var(--fm-accent-ground);
  color: var(--fm-accent-ground-ink);
  border-radius: var(--fm-radius);
  padding: calc(0.18em * var(--fm-h-fit, 1)) calc(0.45em * var(--fm-h-fit, 1));
  max-width: calc(14em * var(--fm-h-fit, 1));
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}
.fm-cover.fm-cover--block .fm-dek { max-width: 36em; }

/* ── Steps: a numbered process list ───────────────────────────────────────── */
/* The numbers are a CSS counter, so the author writes plain paragraphs and
   never renumbers by hand when a step is inserted. */
.fm-steps {
  counter-reset: fm-step;
  margin: 1.6em 0;
  --fm-mt: 1.6em;
  --fm-mb: 1.6em;
  border: var(--fm-border-width) solid var(--fm-border);
  border-radius: var(--fm-radius);
  background: var(--fm-surface);
}
.fm-steps > * {
  counter-increment: fm-step;
  position: relative;
  margin: 0;
  padding: 1em calc(1.2em - var(--fm-border-give, 0px)) 1em calc(4.2em - var(--fm-border-give, 0px));
  border-bottom: 1px solid var(--fm-border);
}
/* The container's border at the theme's width comes out of the items it
   frames (--fm-border-give): the first item's top, the last item's bottom. */
.fm-steps > :first-child { padding-top: calc(1em - var(--fm-border-give, 0px)); }
.fm-steps > :last-child { border-bottom: none; padding-bottom: calc(1em - var(--fm-border-give, 0px)); }
.fm-steps > *::before {
  content: counter(fm-step, decimal-leading-zero);
  position: absolute;
  left: 1.2em;
  top: 1em;
  font-family: var(--fm-font-heading);
  font-weight: 700;
  font-size: 0.85em;
  line-height: 1.5;
  color: var(--fm-accent-text);
}

/* ── Numbered sections (report numbering=sections) ────────────────────────── */
/* Only TOP-LEVEL headings are numbered: a heading inside a block is not a
   document section (the format's own rule), so a band or a card can hold one
   without disturbing the sequence. The counters live on the document root,
   which is where readFastrDocumentSettings puts the class. */
.fm-doc--numbered { counter-reset: fm-sec 0; }
.fm-doc--numbered body > .fm-numbered--sec {
  counter-increment: fm-sec;
  counter-reset: fm-sub 0;
}
.fm-doc--numbered body > .fm-numbered--sec::before {
  content: counter(fm-sec) ". ";
  color: var(--fm-accent-text);
}
.fm-doc--numbered body > .fm-numbered--sub { counter-increment: fm-sub; }
.fm-doc--numbered body > .fm-numbered--sub::before {
  content: counter(fm-sec) "." counter(fm-sub) " ";
  color: var(--fm-accent-text);
}

/* ── Table of contents ────────────────────────────────────────────────────── */
/* The list is the document's own outline (the renderer fills it in), so the
   only job here is to make it read as a contents page: a quiet panel, the
   levels stepped by indent, the entries as plain ink rather than links. */
.fm-toc {
  display: block;
  margin: 1.6em 0;
  --fm-mt: 1.6em;
  --fm-mb: 1.6em;
  padding: calc(1.2em - var(--fm-border-give, 0px)) calc(1.4em - var(--fm-border-give, 0px));
  border: var(--fm-border-width) solid var(--fm-border);
  border-radius: var(--fm-radius);
  background: var(--fm-surface);
}
.fm-toc__title {
  font-family: var(--fm-font-heading);
  font-weight: var(--fm-heading-weight);
  letter-spacing: var(--fm-heading-tracking);
  text-transform: var(--fm-heading-case);
  font-size: 0.85em;
  margin-bottom: 0.7em;
  color: var(--fm-accent-text);
}
.fm-toc__list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.fm-toc__item {
  margin: 0;
  padding: 0.25em 0;
  border-bottom: 1px solid var(--fm-border);
}
.fm-toc__item:last-child { border-bottom: none; }
/* A long contents list (FASTR_TOC_COLUMNS_FROM entries and more) runs in two
   columns, so the block stays under a page's height. */
.fm-toc__list--columns { columns: 2; column-gap: 2em; }
.fm-toc__list--columns .fm-toc__item { break-inside: avoid; }
.fm-toc__item--2 { padding-left: 1.2em; }
.fm-toc__item--3 { padding-left: 2.4em; font-size: 0.95em; }
.fm-toc__item--4, .fm-toc__item--5, .fm-toc__item--6 {
  padding-left: 3.6em;
  font-size: 0.95em;
}
.fm-toc__item a {
  color: var(--fm-ink);
  text-decoration: none;
  border-bottom: none;
}
.fm-toc__item a:hover { color: var(--fm-accent-text); }
.fm-toc__empty {
  color: var(--fm-ink-muted);
  font-style: italic;
}

/* A top-level h1 is deliberately NOT special: the title page is :::cover's
   job, and an opening # heading is just a heading. The only concession is
   standard typography — the document's first element drops its top margin.
   :where() keeps the rule at zero specificity so a first-child cover/band
   still wins with its own negative bleed margin. */
body > :where(:first-child) { margin-top: 0; }

/* ── Image backgrounds (resolved from the image registry at render time) ──── */
.fm-has-bgimage {
  position: relative;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  isolation: isolate;
}
.fm-has-bgimage > * { position: relative; z-index: 1; }
.fm-overlay::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}
.fm-overlay--dark::before { background: rgba(0, 0, 0, 0.55); }
.fm-overlay--light::before { background: rgba(255, 255, 255, 0.72); }

/* ── Figure widths ────────────────────────────────────────────────────────── */
/* small and medium are shares of the column (--fm-fig-share, with the figure
   rules above). width=wide (accepted, still classed fm-figure--wide) once
   overhung the column by up to 4rem a side: on a paged sheet that crosses
   the margin line and reads as a mistake, not a design (Nick, 2026-09-10),
   so it is the column now. width=full bleeds edge to edge, as a band does. */
.fm-figure--full {
  margin: 2em var(--fm-bleed-margin);
}
.fm-figure--full .fm-figure__caption {
  padding-inline: var(--fm-bleed-pad);
}

/* ── Logos (:::logos) ─────────────────────────────────────────────────────── */
/* A row of logos at ONE height: the size sets the row's box, each logo takes
   the height and its own width, so the block's height is known before any
   image has loaded (the page layout measures it straight away). A logo that
   would overflow the row shrinks with its aspect kept. */
.fm-logos {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 1.6em;
  box-sizing: content-box;
  height: 3em;
  margin: 1.2em 0;
  --fm-mt: 1.2em;
  --fm-mb: 1.2em;
}
.fm-logos--s { height: 2em; }
.fm-logos--l { height: 4.5em; }
.fm-logos--center { justify-content: center; }
.fm-logos--right { justify-content: flex-end; }
.fm-logos--spread { justify-content: space-between; }
.fm-logos > .fm-logo {
  display: block;
  flex: 0 1 auto;
  min-width: 0;
  width: auto;
  max-width: 100%;
  height: 100%;
  margin: 0;
  object-fit: contain;
}
.fm-logos.fm-tone, .fm-logos.fm-has-bg, .fm-logos.fm-has-bgimage {
  padding: 0.9em 1.1em;
  border-radius: var(--fm-radius);
}
.fm-tiles .fm-logos, .fm-columns .fm-logos { margin: 0; }

/* ── Page templates (:::page) ─────────────────────────────────────────────── */
.fm-tpl {
  display: grid;
  box-sizing: border-box;
  height: calc(var(--fm-page-area, 245mm) - 8px);
  margin: 0;
  --fm-mt: 0;
  --fm-mb: 0;
  padding: var(--fm-tpl-pad, 0);
  gap: 1.2em 2em;
  grid-template-columns: minmax(0, 1fr);
  align-content: start;
  overflow: hidden;
  position: relative;
}
/* A ground needs room inside it where no page is painted under it (the .html
   export); the editor and print paint the whole sheet and zero this. */
.fm-tpl.fm-tone, .fm-tpl.fm-has-bg, .fm-tpl.fm-has-bgimage {
  --fm-tpl-pad: 2em;
}
.fm-tpl > * { min-width: 0; min-height: 0; overflow: hidden; margin: 0; }
.fm-tpl-main > :first-child, .fm-tpl-slot > :first-child { margin-top: 0; }
.fm-tpl-main > :last-child, .fm-tpl-slot > :last-child { margin-bottom: 0; }
.fm-tpl > .fm-kicker { grid-area: kicker; margin: 0; }
.fm-tpl-main { grid-area: main; }
.fm-tpl-slot--media { grid-area: media; }
.fm-tpl-slot--empty { display: none; }
.fm-tpl-slot .fm-figure { margin: 0; }
.fm-tpl-slot .fm-figure__caption { font-size: calc(0.75em / var(--fm-fit-caption, 1)); }
.fm-tpl-slot__title {
  font-family: var(--fm-font-heading);
  font-weight: 700;
  font-size: 1.05em;
  margin-bottom: 0.7em;
}
.fm-tpl-slot__label {
  font-family: var(--fm-font-heading);
  font-size: 0.75em;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--fm-ink-muted);
  margin-bottom: 0.6em;
}
/* Stats in a template are the layout's, not tiles: no panel of their own. */
.fm-tpl-slot > .fm-stat {
  margin: 0;
  background: none;
  padding: 0;
  border: none;
  border-radius: 0;
  box-shadow: none;
}
/* A photo is the area's, not a framed figure. */
.fm-tpl-slot--media .fm-figure {
  border: none;
  padding: 0;
  background: none;
  box-shadow: none;
  border-radius: 0;
}

/* story: the headline in a gutter column beside a rule, the prose to its
   right, a photo across the page. */
.fm-tpl--story {
  grid-template-columns: minmax(0, 0.4fr) minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr) auto auto minmax(0, 1fr) auto;
  grid-template-areas:
    ".      main"
    "kicker main"
    "side   main"
    ".      main"
    "media  media";
  column-gap: 0;
  row-gap: 0;
}
.fm-tpl--story.fm-tpl--media-top {
  grid-template-rows: auto minmax(0, 1fr) auto auto minmax(0, 1fr);
  grid-template-areas:
    "media  media"
    ".      main"
    "kicker main"
    "side   main"
    ".      main";
}
.fm-tpl--story > .fm-kicker { padding-right: calc(1.6em * var(--fm-fit-kicker, 1)); color: var(--fm-ink); }
.fm-tpl--story .fm-tpl-slot--side { grid-area: side; padding-right: 1.6em; }
.fm-tpl--story .fm-tpl-slot--side::before {
  content: "";
  display: block;
  height: 0.45em;
  width: 80%;
  background: var(--fm-accent);
  margin-bottom: 0.9em;
}
.fm-tpl--story .fm-tpl-slot--side :is(h1, h2, h3) {
  margin: 0;
  color: var(--fm-accent-text);
  line-height: calc(1.15 * var(--fm-h-fit, 1));
}
.fm-tpl--story .fm-tpl-main {
  border-left: var(--fm-border-width) solid var(--fm-accent);
  padding: 1.5em 0 1.5em calc(1.8em - var(--fm-border-give, 0px));
  align-self: stretch;
}
.fm-tpl--story .fm-tpl-slot--media { margin-top: 1.4em; }
.fm-tpl--story.fm-tpl--media-top .fm-tpl-slot--media { margin: 0 0 1.4em; }
.fm-tpl--story .fm-tpl-slot--media img {
  display: block;
  width: 100%;
  max-width: none;
  height: calc(var(--fm-page-area, 245mm) * 0.4);
  max-height: none;
  object-fit: cover;
}

/* summary: a heading and standfirst, the headline totals under gradient
   caps, a heavy rule, then the breakdown on heavy bars. The headline totals
   are set at hero size in the middle of the page and the breakdown stands on
   its foot, so the space between them is the layout's, not a page left
   unfinished. */
.fm-tpl--summary {
  grid-template-rows: auto auto minmax(min-content, 1fr) auto;
  grid-template-areas: "kicker" "main" "headline" "breakdown";
  row-gap: 1.8em;
}
.fm-tpl--summary .fm-tpl-main {
  border-top: 0.2em solid var(--fm-accent);
  padding-top: 1em;
}
.fm-tpl--summary .fm-tpl-main :is(h1, h2) { margin: 0 0 calc(0.4em * var(--fm-h-fit, 1)); color: var(--fm-accent-text); }
.fm-tpl--summary .fm-tpl-slot--headline {
  grid-area: headline;
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(0, 1fr);
  align-content: center;
  gap: 1em;
  text-align: center;
}
.fm-tpl--summary .fm-tpl-slot--headline > .fm-stat::before {
  content: "";
  display: block;
  height: 1.1em;
  margin-bottom: 1em;
  border-radius: min(var(--fm-radius), 0.3em);
  background: linear-gradient(90deg, color-mix(in srgb, var(--fm-accent-ground) 70%, var(--fm-page)), var(--fm-accent-ground));
}
.fm-tpl--summary .fm-tpl-slot--headline > .fm-stat:nth-child(2)::before {
  background: linear-gradient(90deg, var(--fm-accent-ground), color-mix(in srgb, var(--fm-accent-ground) 55%, var(--fm-ink-ground)));
}
.fm-tpl--summary .fm-tpl-slot--headline > .fm-stat:nth-child(3)::before {
  background: linear-gradient(90deg, color-mix(in srgb, var(--fm-accent-ground) 55%, var(--fm-ink-ground)), var(--fm-ink-ground));
}
/* Hero size, but never wider than its column: a stat is its own container,
   so a longer value sets smaller rather than running into its neighbour. */
.fm-tpl--summary .fm-tpl-slot--headline > .fm-stat { container-type: inline-size; }
.fm-tpl--summary .fm-tpl-slot--headline .fm-stat__value { font-size: calc(min(4.8em, 25cqi) / var(--fm-fit-stat-value, 1)); white-space: nowrap; }
.fm-tpl--summary .fm-tpl-slot--headline .fm-stat__label {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--fm-ink);
}
.fm-tpl--summary .fm-tpl-slot--breakdown {
  grid-area: breakdown;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  align-content: start;
  gap: 1.6em 1.2em;
  border-top: 0.7em solid var(--fm-ink-ground);
  padding-top: 1.2em;
}
.fm-tpl--summary .fm-tpl-slot--breakdown > .fm-tpl-slot__title { grid-column: 1 / -1; margin: 0; }
.fm-tpl--summary .fm-tpl-slot--breakdown > .fm-stat {
  display: flex;
  flex-direction: column;
  border-bottom: 0.5em solid var(--fm-ink);
  padding-bottom: 0.5em;
}
.fm-tpl--summary .fm-tpl-slot--breakdown .fm-stat__label {
  order: -1;
  margin: 0 0 calc(0.35em * var(--fm-fit-stat-label, 1));
  padding-bottom: calc(0.3em * var(--fm-fit-stat-label, 1) - var(--fm-border-give, 0px));
  border-bottom: var(--fm-border-width) solid var(--fm-border);
  text-transform: uppercase;
  color: var(--fm-ink);
}
.fm-tpl--summary .fm-tpl-slot--breakdown .fm-stat__value { font-size: calc(2.1em / var(--fm-fit-stat-value, 1)); color: var(--fm-ink); }

/* findings: numbered findings in two columns, the number warm when the
   finding's lead is marked as bad news. The rows share what the page has
   left over, so the findings stand on a grid down to its foot rather than
   all at its top; a row is never shorter than its findings (a track of
   minmax(0, 1fr) clipped a long one under the next row's rule), and
   findings that need more than the page run past it, which the page map
   reports as OVERFULL. */
.fm-tpl--findings {
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "kicker" "main" "items";
  row-gap: 1.6em;
}
.fm-tpl--findings > .fm-kicker { color: var(--fm-accent-text); }
.fm-tpl--findings .fm-tpl-main :is(h1, h2) { margin: 0; font-size: calc(2em / var(--fm-h-fit, 1)); }
.fm-tpl--findings .fm-tpl-slot--items {
  grid-area: items;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-auto-rows: minmax(min-content, 1fr);
  gap: 2.4em 2.4em;
  font-size: 1.12em;
  counter-reset: fm-finding;
}
.fm-tpl--findings .fm-tpl-slot--items > p {
  margin: 0;
  counter-increment: fm-finding;
  border-top: 0.15em solid var(--fm-ink);
  padding-top: 0.6em;
}
.fm-tpl--findings .fm-tpl-slot--items > p::before {
  content: counter(fm-finding);
  display: block;
  font-family: var(--fm-font-heading);
  font-weight: var(--fm-heading-weight);
  font-size: 2.8em;
  line-height: 1;
  margin-bottom: 0.15em;
  color: var(--fm-accent-text);
}
.fm-tpl--findings .fm-tpl-slot--items > p:has(.fm-mark--danger)::before { color: var(--fm-danger); }
.fm-tpl--findings .fm-tpl-slot--items > p > strong:first-child {
  display: block;
  font-family: var(--fm-font-heading);
  font-size: 1.12em;
  margin-bottom: 0.3em;
}

/* exec: the headline numbers stacked in a sidebar on a ground, the summary
   and its next steps beside them. */
.fm-tpl--exec {
  grid-template-columns: minmax(0, 0.5fr) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "side kicker" "side main";
  column-gap: 2.2em;
  row-gap: 0;
}
.fm-tpl--exec > .fm-kicker { color: var(--fm-accent-text); margin-bottom: calc(0.6em * var(--fm-fit-kicker, 1)); }
/* A slot on a ground (tone=) is an inset panel: the theme's corners, as
   every other panel in the report has. */
.fm-tpl-slot.fm-tone { border-radius: var(--fm-radius); }
.fm-tpl--exec .fm-tpl-slot--side {
  grid-area: side;
  padding: 2em 1.6em;
  display: flex;
  flex-direction: column;
  gap: 2.2em;
}
.fm-tpl--exec .fm-tpl-slot--side .fm-stat__value { font-size: calc(2.8em / var(--fm-fit-stat-value, 1)); color: inherit; }
.fm-tpl--exec .fm-tpl-slot--side .fm-stat__label { color: inherit; opacity: 0.85; }
.fm-tpl--exec .fm-tpl-main :is(h1, h2) { margin-top: 0; }

/* opener: a large section number, the title and a line or two; an optional
   photo across the foot. */
.fm-tpl--opener {
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  grid-template-areas: "number" "main" "." "media";
  row-gap: 1em;
}
.fm-tpl--opener .fm-tpl__number {
  grid-area: number;
  font-family: var(--fm-font-heading);
  font-weight: var(--fm-heading-weight);
  font-size: 9em;
  line-height: 0.9;
  letter-spacing: -0.03em;
  color: var(--fm-accent-text);
  margin-top: 0.4em;
}
.fm-tpl--opener .fm-tpl-main :is(h1, h2) { font-size: calc(3.2em / var(--fm-h-fit, 1)); margin: 0 0 calc(0.3em * var(--fm-h-fit, 1)); line-height: calc(1.05 * var(--fm-h-fit, 1)); }
.fm-tpl--opener .fm-tpl-main p { font-size: 1.2em; max-width: 30em; }
.fm-tpl--opener .fm-tpl-slot--media img {
  display: block;
  width: 100%;
  max-width: none;
  height: calc(var(--fm-page-area, 245mm) * 0.32);
  max-height: none;
  object-fit: cover;
}
.fm-tpl:not(.fm-tpl--opener) .fm-tpl__number { display: none; }

/* back: everything at the foot of the page under an accent rule. */
.fm-tpl--back {
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "kicker" "." "main";
}
.fm-tpl--back::before {
  content: "";
  position: absolute;
  top: var(--fm-tpl-pad, 0);
  left: var(--fm-tpl-pad, 0);
  width: 30%;
  height: 0.25em;
  background: var(--fm-accent);
}
.fm-tpl--back .fm-tpl-main {
  font-size: 0.9em;
  border-top: var(--fm-border-width) solid var(--fm-border);
  padding-top: calc(1.2em - var(--fm-border-give, 0px));
}
.fm-tpl--back .fm-tpl-main .fm-logos { margin: 0 0 1.4em; }
.fm-tpl--back .fm-tpl-main p:last-child { font-size: 0.85em; color: var(--fm-ink-muted); }

/* boxed: two columns of running prose over a boxed aside and its notes. */
.fm-tpl--boxed {
  grid-template-rows: auto minmax(0, 1fr) auto auto;
  grid-template-areas: "kicker" "main" "box" "notes";
  row-gap: 1.4em;
}
.fm-tpl--boxed .fm-tpl-main { column-count: 2; column-gap: 1.8em; }
.fm-tpl--boxed .fm-tpl-main :is(h1, h2, h3) { column-span: all; margin-top: 0; color: var(--fm-accent-text); }
.fm-tpl--boxed .fm-tpl-slot--box {
  grid-area: box;
  background: var(--fm-surface-alt);
  border-radius: var(--fm-radius);
  padding: 1.4em 1.6em;
  column-count: 2;
  column-gap: 1.8em;
  font-size: 0.92em;
}
.fm-tpl--boxed .fm-tpl-slot--box > .fm-tpl-slot__title {
  column-span: all;
  padding-bottom: calc(0.5em - var(--fm-border-give, 0px));
  border-bottom: var(--fm-border-width) solid var(--fm-border);
}
.fm-tpl--boxed .fm-tpl-slot--notes { grid-area: notes; font-size: 0.78em; color: var(--fm-ink-muted); }

/* targets: a board of cards, each goal's figure set large, a rule and where
   the country stands today at its foot. */
.fm-tpl--targets {
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "kicker" "main" "cards";
  row-gap: 1.4em;
}
.fm-tpl--targets .fm-tpl-main :is(h1, h2) { margin: 0 0 calc(0.3em * var(--fm-h-fit, 1)); font-size: calc(2.2em / var(--fm-h-fit, 1)); }
.fm-tpl--targets .fm-tpl-slot--cards {
  grid-area: cards;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-auto-rows: minmax(0, 1fr);
  gap: 0.9em;
}
.fm-tpl--targets .fm-card {
  margin: 0;
  background: none;
  border: 0.1em solid color-mix(in srgb, currentColor 70%, transparent);
  border-radius: var(--fm-radius);
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  font-size: 0.9em;
}
.fm-tpl--targets .fm-card__title {
  font-size: calc(0.85em / var(--fm-fit-card-title, 1));
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.fm-tpl--targets .fm-card p strong {
  font-family: var(--fm-font-heading);
  font-size: 2em;
  line-height: 1.05;
}
.fm-card__progress {
  margin-top: auto;
  padding-top: 0.6em;
}
.fm-card__progress-label {
  font-size: 0.72em;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border-bottom: var(--fm-border-width) solid currentColor;
  padding-bottom: calc(0.25em - var(--fm-border-give, 0px));
}
.fm-card__progress-value {
  text-align: right;
  font-family: var(--fm-font-heading);
  font-weight: var(--fm-heading-weight);
  font-size: 1.3em;
  margin-top: 0.15em;
}

/* compare: two halves on contrasting grounds, the change on the seam. Each
   half's few lines sit centred on its ground, level with the change, so the
   grounds read as a poster rather than a page stopped half way. Both halves
   clear the disc on the seam. */
.fm-tpl--compare {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "kicker kicker" "main main" "left right";
  column-gap: 0;
  row-gap: 1.2em;
}
.fm-tpl--compare .fm-tpl-main :is(h1, h2) { margin-top: 0; }
.fm-tpl--compare .fm-tpl-slot--left { grid-area: left; }
.fm-tpl--compare .fm-tpl-slot--right { grid-area: right; }
.fm-tpl--compare .fm-tpl-slot--left, .fm-tpl--compare .fm-tpl-slot--right {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 2.4em 2em;
}
.fm-tpl--compare .fm-tpl-slot--left { padding-right: 3.4em; }
/* The halves meet at the seam: only their outer corners round. */
.fm-tpl--compare .fm-tpl-slot--left.fm-tone { border-radius: var(--fm-radius) 0 0 var(--fm-radius); }
.fm-tpl--compare .fm-tpl-slot--right.fm-tone { border-radius: 0 var(--fm-radius) var(--fm-radius) 0; }
.fm-tpl--compare .fm-tpl-slot--right { padding-left: 3.4em; }
.fm-tpl--compare .fm-tpl-slot .fm-stat__value { font-size: calc(4.2em / var(--fm-fit-stat-value, 1)); color: inherit; }
.fm-tpl--compare .fm-tpl-slot .fm-stat__label { color: inherit; font-size: calc(1em / var(--fm-fit-stat-label, 1)); margin-bottom: calc(1.2em * var(--fm-fit-stat-label, 1)); }
.fm-tpl--compare .fm-tpl-slot .fm-tpl-slot__label { color: inherit; opacity: 0.8; }
.fm-tpl--compare .fm-tpl__delta {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 1;
  width: 5.6em;
  height: 5.6em;
  border-radius: calc(var(--fm-radius) * 999);
  display: grid;
  place-items: center;
  background: var(--fm-page);
  color: var(--fm-accent-text);
  font-family: var(--fm-font-heading);
  font-weight: var(--fm-heading-weight);
  font-size: 1.1em;
  box-shadow: 0 0.1em 0.5em color-mix(in srgb, var(--fm-ink) 25%, transparent);
}
.fm-tpl:not(.fm-tpl--compare) .fm-tpl__delta { display: none; }

/* timeline: milestones alternating either side of a spine, spread down
   its whole length. */
.fm-tpl--timeline {
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "kicker" "main" "events";
  row-gap: 1.6em;
}
.fm-tpl--timeline .fm-tpl-main :is(h1, h2) { margin: 0; }
.fm-tpl--timeline .fm-tpl-slot--events {
  grid-area: events;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 1.4em;
  font-size: 1.1em;
}
.fm-tpl--timeline .fm-tpl-slot--events::before {
  content: "";
  position: absolute;
  left: calc(50% - 0.1em);
  top: 0;
  bottom: 0;
  width: 0.2em;
  background: var(--fm-accent);
}
.fm-tpl--timeline .fm-tpl-slot--events > p { position: relative; margin: 0; width: 44%; }
.fm-tpl--timeline .fm-tpl-slot--events > p:nth-child(odd) { text-align: right; }
.fm-tpl--timeline .fm-tpl-slot--events > p:nth-child(even) { margin-left: 56%; }
.fm-tpl--timeline .fm-tpl-slot--events > p::after {
  content: "";
  position: absolute;
  top: 0.3em;
  width: 0.9em;
  height: 0.9em;
  border-radius: calc(var(--fm-radius) * 999);
  background: var(--fm-accent);
  border: 0.2em solid var(--fm-page);
}
.fm-tpl--timeline .fm-tpl-slot--events > p:nth-child(odd)::after { right: calc(-6% / 0.44 - 0.65em); }
.fm-tpl--timeline .fm-tpl-slot--events > p:nth-child(even)::after { left: calc(-6% / 0.44 - 0.65em); }
.fm-tpl--timeline .fm-tpl-slot--events > p:has(.fm-mark--danger)::after { background: var(--fm-danger); }
.fm-tpl--timeline .fm-tpl-slot--events > p > strong:first-child {
  display: block;
  font-family: var(--fm-font-heading);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--fm-accent-text);
}

/* voices: a photo, a pull quote on a card over its lower edge, context. */
.fm-tpl--voices {
  grid-template-rows: auto auto auto minmax(0, 1fr);
  grid-template-areas: "kicker" "media" "quote" "main";
  row-gap: 0;
}
.fm-tpl--voices .fm-tpl-slot--media img {
  display: block;
  width: 100%;
  max-width: none;
  height: calc(var(--fm-page-area, 245mm) * 0.5);
  max-height: none;
  object-fit: cover;
}
.fm-tpl--voices .fm-tpl-slot--quote {
  grid-area: quote;
  position: relative;
  z-index: 1;
  margin: -4.5em 7% 1.6em;
  padding: 1.6em 1.8em 1.4em;
  background: var(--fm-page);
  border-radius: var(--fm-radius);
  font-family: var(--fm-font-heading);
  font-size: 1.35em;
  line-height: 1.3;
  box-shadow: 0 0.1em 0.6em color-mix(in srgb, var(--fm-ink) 18%, transparent);
}
.fm-tpl--voices .fm-tpl-slot--empty + .fm-tpl-slot--quote,
.fm-tpl--voices .fm-tpl-slot--quote:first-child {
  margin-top: 0;
}
.fm-tpl--voices .fm-tpl-slot--quote::before {
  content: "\201C";
  display: block;
  font-size: 2.6em;
  line-height: 0.6;
  color: var(--fm-accent-text);
}
.fm-tpl--voices .fm-tpl-slot--quote > p {
  font-size: calc(1em / var(--fm-fit-quote, 1));
  line-height: calc(1.3 * var(--fm-fit-quote, 1));
}
.fm-tpl--voices .fm-tpl-slot--quote .fm-quote__cite {
  display: block;
  margin-top: calc(0.8em * var(--fm-fit-cite, 1));
  font-family: var(--fm-font-body);
  font-size: calc(0.55em / var(--fm-fit-cite, 1));
  line-height: calc(1.3 * var(--fm-fit-cite, 1));
  font-style: normal;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--fm-accent-text);
}
.fm-tpl--voices .fm-tpl-slot--media .fm-figure__caption { display: none; }
.fm-tpl--voices .fm-tpl-main { max-width: 34em; }

/* spotlight: the prose in a column; beside it a short paragraph, then a
   panel (the portrait and the quote, both on the accent ground) running to
   the sheet's right edge. The template reaches the edge through the bleed
   margin, and the right column's padding brings its text back to the
   measure, as a band does. */
.fm-tpl--spotlight {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "main top" "main media" "main quote";
  column-gap: 2.2em;
  row-gap: 0;
  margin-right: var(--fm-bleed-margin);
  --fm-tpl-fill: main;
}
.fm-tpl--spotlight .fm-tpl-main :is(h1, h2) { margin-top: 0; }
/* The panel starts a fifth of the way down at least, as a short paragraph
   above it would otherwise lift it to the top and leave its foot empty. */
.fm-tpl--spotlight .fm-tpl-slot--top {
  grid-area: top;
  min-height: calc(var(--fm-page-area, 245mm) * 0.2);
  box-sizing: border-box;
  padding: 0 var(--fm-bleed-pad) 2em 0;
}
.fm-tpl--spotlight .fm-tpl-slot--media {
  padding: 2.6em var(--fm-bleed-pad) 0 2.4em;
}
.fm-tpl--spotlight .fm-tpl-slot--media img {
  display: block;
  width: 64%;
  max-width: none;
  height: auto;
  max-height: none;
  aspect-ratio: 1;
  margin: 0 auto;
  border-radius: calc(var(--fm-radius) * 999);
  object-fit: cover;
}
.fm-tpl--spotlight .fm-tpl-slot--media .fm-figure__caption { display: none; }
/* The editor's Add photo box, where the portrait will stand: a dashed
   circle inside the panel, which stays one ground. */
.fm-tpl--spotlight .fm-tpl-slot--empty.fm-tpl-slot--media {
  min-height: 0;
  border: none;
  border-radius: 0;
}
.fm-tpl--spotlight .fm-tpl-slot--empty.fm-tpl-slot--media::after {
  display: grid;
  place-items: center;
  width: 64%;
  aspect-ratio: 1;
  border: 2px dashed currentColor;
  border-radius: calc(var(--fm-radius) * 999);
  opacity: 0.85;
}
.fm-tpl--spotlight .fm-tpl-slot--quote {
  grid-area: quote;
  padding: 2.4em var(--fm-bleed-pad) 2.4em 2.4em;
  font-family: var(--fm-font-heading);
  font-weight: var(--fm-heading-weight);
  font-size: 1.5em;
  line-height: 1.25;
}
.fm-tpl--spotlight .fm-tpl-slot--quote::before {
  content: "\201C";
  display: block;
  font-size: 2.2em;
  line-height: 0.7;
  margin-bottom: 0.1em;
}
.fm-tpl--spotlight .fm-tpl-slot--quote > p {
  font-size: calc(1em / var(--fm-fit-quote, 1));
  line-height: calc(1.25 * var(--fm-fit-quote, 1));
}
.fm-tpl--spotlight .fm-tpl-slot--quote .fm-quote__cite {
  display: block;
  margin-top: calc(1.2em * var(--fm-fit-cite, 1));
  font-family: var(--fm-font-body);
  font-size: calc(0.55em / var(--fm-fit-cite, 1));
  font-style: normal;
  font-weight: 700;
  line-height: calc(1.4 * var(--fm-fit-cite, 1));
}

/* feature: the heading, a bold lead and the prose in a column; the photo
   fills the rest of the page, out to the sheet's right edge. */
.fm-tpl--feature {
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "kicker media" "main media";
  column-gap: 2.4em;
  row-gap: 0;
  margin-right: var(--fm-bleed-margin);
  --fm-tpl-fill: main;
}
.fm-tpl--feature > .fm-kicker { margin-bottom: calc(0.8em * var(--fm-fit-kicker, 1)); }
.fm-tpl--feature .fm-tpl-main :is(h1, h2) { margin-top: 0; }
.fm-tpl--feature .fm-tpl-slot--media .fm-figure { height: 100%; }
.fm-tpl--feature .fm-tpl-slot--media img {
  display: block;
  width: 100%;
  max-width: none;
  height: 100%;
  max-height: none;
  object-fit: cover;
}
.fm-tpl--feature .fm-tpl-slot--media .fm-figure__caption { display: none; }

/* profile: a map and a column of facts under the district's name. */
.fm-tpl--profile {
  grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "kicker kicker" "main main" "map facts";
  row-gap: 1.2em;
}
.fm-tpl--profile > .fm-kicker { color: var(--fm-accent-text); }
.fm-tpl--profile .fm-tpl-main :is(h1, h2) {
  margin: 0 0 calc(0.4em * var(--fm-h-fit, 1));
  font-size: calc(2.4em / var(--fm-h-fit, 1));
  padding-bottom: calc(0.3em * var(--fm-h-fit, 1));
  border-bottom: calc(0.08em * var(--fm-h-fit, 1)) solid var(--fm-ink);
}
.fm-tpl--profile .fm-tpl-slot--map { grid-area: map; }
.fm-tpl--profile .fm-tpl-slot--map img { width: 100%; height: auto; max-height: 100%; object-fit: contain; }
.fm-tpl--profile .fm-tpl-slot--facts {
  grid-area: facts;
  display: flex;
  flex-direction: column;
  gap: 1.4em;
}
.fm-tpl--profile .fm-tpl-slot--facts > .fm-stat {
  border-bottom: var(--fm-border-width) solid var(--fm-border);
  padding-bottom: calc(0.7em - var(--fm-border-give, 0px));
  display: flex;
  flex-direction: column;
}
.fm-tpl--profile .fm-tpl-slot--facts .fm-stat__label {
  order: -1;
  margin: 0 0 calc(0.2em * var(--fm-fit-stat-label, 1));
  font-size: calc(0.72em / var(--fm-fit-stat-label, 1));
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.fm-tpl--profile .fm-tpl-slot--facts .fm-stat__value { font-size: calc(2.4em / var(--fm-fit-stat-value, 1)); }
.fm-tpl--profile .fm-tpl-slot--facts .fm-stat__delta { align-self: flex-start; }

/* method: short panels in a grid, the citation at the foot. */
.fm-tpl--method {
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  grid-template-areas: "kicker" "main" "panels" "cite";
  row-gap: 1.4em;
  --fm-tpl-fill: panels;
}
.fm-tpl--method .fm-tpl-main :is(h1, h2) { margin: 0; }
.fm-tpl--method .fm-tpl-slot--panels {
  grid-area: panels;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-content: start;
  gap: 1.8em 2.2em;
}
.fm-tpl--method .fm-card { margin: 0; background: none; border: none; padding: 0; font-size: 0.95em; }
.fm-tpl--method .fm-card__title { font-size: calc(1.1em / var(--fm-fit-card-title, 1)); }
.fm-tpl--method .fm-tpl-slot--cite {
  grid-area: cite;
  background: var(--fm-page);
  border-radius: var(--fm-radius);
  padding: 1.1em 1.3em;
  font-size: 0.88em;
}

/* ladder: results stacked as full-width bars stepping from the accent to
   the ink, each with an icon disc rising from its foot. */
.fm-tpl--ladder {
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "kicker" "main" "rows";
  row-gap: 1.4em;
}
.fm-tpl--ladder > .fm-kicker { color: var(--fm-accent-text); }
.fm-tpl--ladder .fm-tpl-main {
  border-bottom: 0.25em solid var(--fm-accent);
  padding-bottom: 0.8em;
}
.fm-tpl--ladder .fm-tpl-main :is(h1, h2) { margin: 0 0 calc(0.3em * var(--fm-h-fit, 1)); text-transform: uppercase; }
.fm-tpl--ladder .fm-tpl-slot--rows {
  grid-area: rows;
  display: grid;
  grid-auto-rows: minmax(0, 1fr);
  gap: 0.4em;
}
.fm-tpl--ladder .fm-tpl-slot--rows > .fm-stat {
  position: relative;
  overflow: hidden;
  display: grid;
  grid-template-columns: 24% minmax(0, 1fr) minmax(0, 0.8fr);
  grid-template-areas: "icon value label";
  align-items: center;
  column-gap: 1.2em;
  padding: 0 1.4em 0 0;
  border-radius: var(--fm-radius);
  color: var(--fm-ink-ground-ink);
  background: color-mix(in srgb, var(--fm-accent-ground) var(--fm-rung, 100%), var(--fm-ink-ground));
}
.fm-tpl--ladder .fm-tpl-slot--rows > .fm-stat:nth-child(2) { --fm-rung: 78%; }
.fm-tpl--ladder .fm-tpl-slot--rows > .fm-stat:nth-child(3) { --fm-rung: 56%; }
.fm-tpl--ladder .fm-tpl-slot--rows > .fm-stat:nth-child(4) { --fm-rung: 34%; }
.fm-tpl--ladder .fm-tpl-slot--rows > .fm-stat:nth-child(5) { --fm-rung: 14%; }
.fm-tpl--ladder .fm-tpl-slot--rows > .fm-stat:nth-child(6) { --fm-rung: 0%; }
.fm-tpl--ladder .fm-tpl-slot--rows .fm-icon {
  grid-area: icon;
  align-self: end;
  justify-self: center;
  width: 3.6em;
  height: 3.6em;
  margin: 0 0 -0.6em;
  padding: 0.9em;
  border-radius: calc(var(--fm-radius) * 999);
  box-sizing: content-box;
  color: var(--fm-ink-ground);
  background: var(--fm-page);
  -webkit-mask: none;
  mask: none;
  position: relative;
}
.fm-tpl--ladder .fm-tpl-slot--rows .fm-icon::after {
  content: "";
  position: absolute;
  inset: 0.9em;
  background: currentColor;
  -webkit-mask: var(--fm-icon) center / contain no-repeat;
  mask: var(--fm-icon) center / contain no-repeat;
}
.fm-tpl--ladder .fm-tpl-slot--rows .fm-stat__value {
  grid-area: value;
  font-size: calc(3em / var(--fm-fit-stat-value, 1));
  text-align: right;
  color: inherit;
}
.fm-tpl--ladder .fm-tpl-slot--rows .fm-stat__label {
  grid-area: label;
  margin: 0;
  font-size: calc(0.95em / var(--fm-fit-stat-label, 1));
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: inherit;
}

/* scorecard: a table whose cells fill with the status their mark names. The
   table takes the page down to the notes, its rows sharing the height. */
.fm-tpl--scorecard {
  grid-template-rows: auto auto minmax(min-content, 1fr) auto;
  grid-template-areas: "kicker" "main" "table" "notes";
  row-gap: 1.2em;
}
.fm-tpl--scorecard .fm-tpl-main :is(h1, h2) { margin: 0 0 calc(0.3em * var(--fm-h-fit, 1)); }
.fm-tpl--scorecard .fm-tpl-slot--table { grid-area: table; }
.fm-tpl--scorecard .fm-tpl-slot--notes { grid-area: notes; font-size: 0.82em; color: var(--fm-ink-muted); }
.fm-tpl--scorecard table { width: 100%; height: 100%; margin: 0; border-collapse: separate; border-spacing: 0.2em; font-size: 1.1em; }
.fm-tpl--scorecard td, .fm-tpl--scorecard th { padding: 0.55em 0.7em; border: none; vertical-align: middle; }
.fm-tpl--scorecard th { padding: calc(0.55em * var(--fm-fit-th, 1)) calc(0.7em * var(--fm-fit-th, 1)); }
.fm-tpl--scorecard td:has(> .fm-mark--success) { background: color-mix(in srgb, var(--fm-success) 22%, transparent); }
.fm-tpl--scorecard td:has(> .fm-mark--warning) { background: color-mix(in srgb, var(--fm-warning) 22%, transparent); }
.fm-tpl--scorecard td:has(> .fm-mark--danger) { background: color-mix(in srgb, var(--fm-danger) 22%, transparent); }
.fm-tpl--scorecard td:has(> .fm-mark--info) { background: color-mix(in srgb, var(--fm-info) 22%, transparent); }
.fm-tpl--scorecard td > .fm-mark { font-weight: 700; }

/* ── Icons (icon= on a stat or a card) ────────────────────────────────────── */
.fm-icon {
  display: inline-block;
  width: 1.6em;
  height: 1.6em;
  background: currentColor;
  -webkit-mask: var(--fm-icon) center / contain no-repeat;
  mask: var(--fm-icon) center / contain no-repeat;
}
.fm-stat > .fm-icon, .fm-card > .fm-icon {
  display: block;
  margin-bottom: 0.5em;
  color: var(--fm-accent-text);
}
