@import url('https://fonts.googleapis.com/css2?family=Roboto+Condensed:ital,wght@0,400;0,700;1,400&display=swap');
:root {
  --fm-page: #ffffff;
  --fm-paper: #ffffff;
  --fm-warm: #b0644e;
  --fm-light-ink: #f7fbff;
  --fm-dark-ink: #1f2b4a;
  --fm-surface: #eef3f8;
  --fm-surface-alt: #e6eaf1;
  --fm-ink: #1f2b4a;
  --fm-ink-muted: #717a8f;
  --fm-accent: #6b7eb7;
  --fm-border: #d0d6de;
  --fm-radius: 0px;
  --fm-border-width: 1px;
  /* What a border at the theme's width takes beyond the default theme's
     1px: every structure rule drawn at --fm-border-width gives it back out
     of the padding beside it, so a heavier theme's boxes stand as tall and
     hold as wide a column as the default theme's (FASTR_THEME_SPECS). */
  --fm-border-give: calc(1px - 1px);
  --fm-body-tracking: 0em;
  --fm-body-size: 13.333333333333334px;
  --fm-body-leading: 1.15;
  --fm-bullet: "\2d ";
  --fm-fit-caption: 1;
  --fm-fit-callout-title: 1;
  --fm-fit-card-title: 1;
  --fm-fit-stat-value: 1;
  --fm-fit-stat-label: 1;
  --fm-fit-kicker: 1;
  --fm-fit-th: 1;
  --fm-fit-quote: 1;
  --fm-fit-cite: 1;
  --fm-font-body: "Roboto Condensed", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --fm-font-heading: "Roboto Condensed", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --fm-heading-weight: 700;
  --fm-heading-tracking: 0;
  --fm-heading-case: none;
  --fm-measure: 60rem;
  --fm-callout-color: #6b7eb7;
  --fm-h1-size: 2.4em;
  --fm-h1-weight: var(--fm-heading-weight);
  --fm-h1-line-height: 1.15;
  --fm-h1-fit: 1;
  --fm-h2-size: 1.8em;
  --fm-h2-weight: var(--fm-heading-weight);
  --fm-h2-line-height: 1.2;
  --fm-h2-fit: 1;
  --fm-h3-size: 1.1em;
  --fm-h3-weight: var(--fm-heading-weight);
  --fm-h3-line-height: 1.25;
  --fm-h3-fit: 1;
  --fm-h4-size: 1em;
  --fm-h4-weight: var(--fm-heading-weight);
  --fm-h4-line-height: 1.2;
  --fm-h4-fit: 1;
  --fm-h5-size: 1em;
  --fm-h5-weight: var(--fm-heading-weight);
  --fm-h5-line-height: 1.2;
  --fm-h5-fit: 1;
  --fm-h6-size: 1em;
  --fm-h6-weight: var(--fm-heading-weight);
  --fm-h6-line-height: 1.2;
  --fm-h6-fit: 1;
  --fm-paper-ground: #e6eaf1;
