  --fm-ink-ground: #1f2b4a;
  --fm-ink-ground-ink: #f7fbff;
  --fm-accent-ground: #6b7eb7;
  --fm-accent-ground-ink: #f7fbff;
  --fm-warm-ground: #b0644e;
  --fm-warm-ground-ink: #f7fbff;
  --fm-accent-text: #6b7eb7;
  --fm-mark-accent-weight: inherit;
  --fm-info-light: #6b7eb7;
