/* A section opens on a full-width navy rule, drawn in the heading's margin. */
:root .fm-live-scope h1 { position: relative; margin-bottom: 0.75em; }
:root .fm-live-scope h1::after { content: ""; position: absolute; left: 0; right: 0; bottom: -0.3em; border-bottom: 1px solid var(--fm-ink); pointer-events: none; }
:root .fm-live-scope h2 { margin-bottom: 0.3em; }
:root .fm-live-scope h3 { margin-top: 1.1em; margin-bottom: 0.45em; }
:root .fm-live-scope p { margin-bottom: 0.8em; }
:root .fm-live-scope li { margin: 0.55em 0; }
/* A figure is a pale panel, its caption (above it: figureCaption) in ink. */
:root .fm-live-scope .fm-figure { background: var(--fm-surface); border-radius: var(--fm-radius); padding: 0.8em 1em 1em; }
:root .fm-live-scope .fm-figure__caption { font-size: 1.15em; line-height: 1.3; color: var(--fm-ink); }
/* Tables on the same panel: a rule under the header and after the row
   labels, light rules between rows. */
:root .fm-live-scope table { background: var(--fm-surface); border-radius: var(--fm-radius); font-size: 1em; }
:root .fm-live-scope thead th { border-bottom: 1px solid var(--fm-ink); padding-bottom: calc(0.5em + 1px); vertical-align: bottom; }
:root .fm-live-scope th:first-child, :root .fm-live-scope td:first-child { border-right: 1px solid var(--fm-ink); }
:root .fm-live-scope tbody tr:last-child td { border-bottom-color: transparent; }
/* Key points: the accent ground, no rule of its own. */
:root .fm-live-scope .fm-callout.fm-tone--accent { border-left-color: transparent; }
:root .fm-live-scope .fm-callout__title { font-weight: 700; }
/* Contents as a page, not a panel: section entries bold. */
:root .fm-live-scope .fm-toc { background: none; border-color: transparent; padding-left: 0; padding-right: 0; }
:root .fm-live-scope .fm-toc__item--1 { font-weight: 700; }
:root .fm-live-scope .fm-stat__value { font-weight: 700; }
:root .fm-live-scope .fm-quote { border-left-color: var(--fm-accent); }

css_custom/assessment:
@import url('https://fonts.googleapis.com/css2?family=Roboto+Condensed:ital,wght@0,400;0,700;1,400&display=swap');
:root {
