.fm-figure { display: grid; }
.fm-figure__caption { grid-row: 1; margin: 0 0 calc(0.5em * var(--fm-fit-caption, 1)); }

/* A section opens on a full-width navy rule, drawn in the heading's margin. */
h1 { position: relative; margin-bottom: 0.75em; }
h1::after { content: ""; position: absolute; left: 0; right: 0; bottom: -0.3em; border-bottom: 1px solid var(--fm-ink); pointer-events: none; }
h2 { margin-bottom: 0.3em; }
h3 { margin-top: 1.1em; margin-bottom: 0.45em; }
p { margin-bottom: 0.8em; }
li { margin: 0.55em 0; }
/* A figure is a pale panel, its caption (above it: figureCaption) in ink. */
