thead th { border-bottom: 1px solid var(--fm-ink); padding-bottom: calc(0.5em + 1px); vertical-align: bottom; }
th:first-child, td:first-child { border-right: 1px solid var(--fm-ink); }
tbody tr:last-child td { border-bottom-color: transparent; }
/* Key points: the accent ground, no rule of its own. */
.fm-callout.fm-tone--accent { border-left-color: transparent; }
.fm-callout__title { font-weight: 700; }
/* Contents as a page, not a panel: section entries bold. */
.fm-toc { background: none; border-color: transparent; padding-left: 0; padding-right: 0; }
.fm-toc__item--1 { font-weight: 700; }
.fm-stat__value { font-weight: 700; }
.fm-quote { border-left-color: var(--fm-accent); }


html { overflow-x: hidden; }


@media (max-width: 640px) {
  .fm-tiles, .fm-columns { grid-template-columns: minmax(0, 1fr) !important; }
